import{_ as a,a as t,c as o,ac as n}from"./chunks/framework.BSuaGltH.js";const p=JSON.parse('{"title":"第三册：培养技能 · Lesson 56 Our neighbour, the river","description":"学习 混合时间条件句，配有原创例句、重点词汇和带解析的自测。","frontmatter":{"title":"第三册：培养技能 · Lesson 56 Our neighbour, the river","description":"学习 混合时间条件句，配有原创例句、重点词汇和带解析的自测。","showdocs":{"topics":[{"id":"english","title":"英语","link":"/topics/english/"}],"kind":"路线与能力起点","scope":"general","audience":"general","group":"学习与记录","seriesTitle":"新概念英语经典版第3册课时","summary":"学习 混合时间条件句，配有原创例句、重点词汇和带解析的自测。","status":"active","related":[{"title":"程序员英语 08：一次完整的阅读与协作实战","link":"/life/english/programmer/practice","kind":"读写与对话练习","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语","link":"/life/english/new-concept/book-2/unit-01/vocabulary","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语 · 第17–24课","link":"/life/english/new-concept/book-2/unit-01/vocabulary-part-02","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语 · 字母索引与第1–16课","link":"/life/english/new-concept/book-2/unit-01/vocabulary-part-01","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 复习与自测","link":"/life/english/new-concept/book-2/unit-01/review","kind":"读写与对话练习","scope":"general","audience":"general"}],"prev":{"text":"第三册：培养技能 · Lesson 55 From the earth: Greetings","link":"/life/english/new-concept/book-3/unit-03/lesson-055"},"next":{"text":"第三册：培养技能 · Lesson 57 Back in the old country","link":"/life/english/new-concept/book-3/unit-03/lesson-057"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"第三册：培养技能 · Lesson 55 From the earth: Greetings","link":"/life/english/new-concept/book-3/unit-03/lesson-055"},"next":{"text":"第三册：培养技能 · Lesson 57 Back in the old country","link":"/life/english/new-concept/book-3/unit-03/lesson-057"}},"headers":[],"relativePath":"life/english/new-concept/book-3/unit-03/lesson-056.md","filePath":"life/english/new-concept/book-3/unit-03/lesson-056.md"}'),r={name:"life/english/new-concept/book-3/unit-03/lesson-056.md"};function i(l,e,s,d,h,c){return t(),o("div",null,[...e[0]||(e[0]=[n('<h1 id="第三册-培养技能-·-lesson-56-our-neighbour-the-river" tabindex="-1">第三册：培养技能 · Lesson 56 Our neighbour, the river <a class="header-anchor" href="#第三册-培养技能-·-lesson-56-our-neighbour-the-river" aria-label="Permalink to &quot;第三册：培养技能 · Lesson 56 Our neighbour, the river&quot;">​</a></h1><p><a href="/life/english/new-concept/overview">系列目录</a> · <a href="/life/english/new-concept/book-3/contents">本册目录</a> · <a href="/life/english/new-concept/book-3/unit-03/overview">单元 3</a></p><h2 id="学习目标与内容导读" tabindex="-1">学习目标与内容导读 <a class="header-anchor" href="#学习目标与内容导读" aria-label="Permalink to &quot;学习目标与内容导读&quot;">​</a></h2><p>围绕河流带来的便利与季节性变化，训练描述长期状态和异常事件。既要写日常亲近，也要说明涨水时的实际限制。学习 mixed conditionals 把过去原因和现在结果连接起来，但避免无理由混用时态，让读者清楚哪个部分属于已过去的选择。</p><p>本课以主题阅读带动语言分析，学习重点如下。</p><h2 id="单词与搭配" tabindex="-1">单词与搭配 <a class="header-anchor" href="#单词与搭配" aria-label="Permalink to &quot;单词与搭配&quot;">​</a></h2><table tabindex="0"><thead><tr><th>单词</th><th>音标</th><th>词性</th><th>本页义项</th><th>搭配</th></tr></thead><tbody><tr><td>bank</td><td>/bæŋk/</td><td>n.</td><td>河岸</td><td>a river bank</td></tr><tr><td>flood</td><td>/flʌd/</td><td>n.</td><td>洪水</td><td>a seasonal flood</td></tr><tr><td>barrier</td><td>/ˈbæriə/</td><td>n.</td><td>屏障</td><td>a temporary barrier</td></tr><tr><td>level</td><td>/ˈlevəl/</td><td>n.</td><td>水位或水平</td><td>the water level</td></tr></tbody></table><h2 id="短语与句型" tabindex="-1">短语与句型 <a class="header-anchor" href="#短语与句型" aria-label="Permalink to &quot;短语与句型&quot;">​</a></h2><ul><li>rise above — 升到某水平之上</li><li>keep out — 阻挡进入</li></ul><h2 id="语法讲解-混合时间条件句" tabindex="-1">语法讲解：混合时间条件句 <a class="header-anchor" href="#语法讲解-混合时间条件句" aria-label="Permalink to &quot;语法讲解：混合时间条件句&quot;">​</a></h2><p>过去反事实条件可与现在结果相连，如 If we had repaired the wall, the room would be dry now。if 从句用 had done 表示过去未实现的动作，主句用 would 加原形描述现在与事实相反的状态。它不同于第三条件句中的 would have done，后者把结果也放在过去。选择混合结构必须有真实的时间联系，不能随意搭配。now、today 等时间词有助于显明结果时点；讨论环境影响时仍应避免把一个条件当作所有结果的唯一原因。</p><h2 id="原创例句与结构分析" tabindex="-1">原创例句与结构分析 <a class="header-anchor" href="#原创例句与结构分析" aria-label="Permalink to &quot;原创例句与结构分析&quot;">​</a></h2><blockquote><p>If we had moved the supplies upstairs yesterday, they would be dry now.</p></blockquote><p>如果我们昨天把补给品搬到楼上，它们现在就会是干的。</p><p>had moved 指昨日未做的动作，would be dry now 表示当前反事实状态。</p><h2 id="易错辨析" tabindex="-1">易错辨析 <a class="header-anchor" href="#易错辨析" aria-label="Permalink to &quot;易错辨析&quot;">​</a></h2><p>would have been dry now 通常不如 would be dry now 清楚，因为这里明确评价现在状态，而非过去已经完成的结果。</p><h2 id="听说训练" tabindex="-1">听说训练 <a class="header-anchor" href="#听说训练" aria-label="Permalink to &quot;听说训练&quot;">​</a></h2><p>朗读 yesterday、now、next rainy season 并各停顿一次，绘出三个时间点，检查自己的复述没有把结果都放到过去。</p><h2 id="读写训练" tabindex="-1">读写训练 <a class="header-anchor" href="#读写训练" aria-label="Permalink to &quot;读写训练&quot;">​</a></h2><h3 id="阅读材料-本站原创" tabindex="-1">阅读材料（本站原创） <a class="header-anchor" href="#阅读材料-本站原创" aria-label="Permalink to &quot;阅读材料（本站原创）&quot;">​</a></h3><p>We left the storage boxes on the ground floor. If we had raised them earlier, the contents would be usable now. Before the next rainy season, we will move the shelves upstairs.</p><h3 id="表达任务" tabindex="-1">表达任务 <a class="header-anchor" href="#表达任务" aria-label="Permalink to &quot;表达任务&quot;">​</a></h3><p>写三句虚构涨水后的复盘，区分过去遗漏、现在影响和下一次准备。</p><details class="details custom-block"><summary>写作提示与点评</summary><p>因果链时间明确，未来措施直接对应此前遗漏。</p></details><h2 id="课后自测" tabindex="-1">课后自测 <a class="header-anchor" href="#课后自测" aria-label="Permalink to &quot;课后自测&quot;">​</a></h2><h3 id="练习-1" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1" aria-label="Permalink to &quot;练习 1&quot;">​</a></h3><p>例句的条件发生在何时？</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> 昨天。</p><p><strong>解析：</strong> yesterday 与 had moved 标明过去。</p></details><h3 id="练习-2" tabindex="-1">练习 2 <a class="header-anchor" href="#练习-2" aria-label="Permalink to &quot;练习 2&quot;">​</a></h3><p>例句结果评价在何时？</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> 现在。</p><p><strong>解析：</strong> now 和 would be 指当前状态。</p></details><h3 id="练习-3" tabindex="-1">练习 3 <a class="header-anchor" href="#练习-3" aria-label="Permalink to &quot;练习 3&quot;">​</a></h3><p>把结果改为“当时就不会损坏”，用过去结果结构。</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> they would not have been damaged then</p><p><strong>解析：</strong> would have been damaged 将结果也置于过去。</p></details><h2 id="复习导航" tabindex="-1">复习导航 <a class="header-anchor" href="#复习导航" aria-label="Permalink to &quot;复习导航&quot;">​</a></h2><p>本课重点：混合时间条件句。复习时先遮住答案重做自测，再将示范中的人物、时间或条件改为自己的情境；解释改动后哪些词需要变化。</p><p><a href="/life/english/new-concept/book-3/unit-03/grammar">单元语法</a> · <a href="/life/english/new-concept/book-3/unit-03/vocabulary">单元单词</a> · <a href="/life/english/new-concept/book-3/unit-03/review">单元自测</a></p><p><a href="/life/english/new-concept/book-3/unit-03/lesson-055">上一课</a> · <a href="/life/english/new-concept/book-3/unit-03/overview">单元目录</a> · <a href="/life/english/new-concept/book-3/unit-03/lesson-057">下一课</a></p><hr><p>本站原创学习伴读：保留经典版课号和课名，讲解、例句与练习独立编写。重点词汇用于本页学习，不等同于教材全部生词表；教材课文、完整译文、原题与录音请配合自己的正版教材使用。</p>',41)])])}const b=a(r,[["render",i]]);export{p as __pageData,b as default};
